<?php
namespace App\Domain\Retention; use App\Models\User; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\DB;
class StreakService { public function recordQualifyingAction(User $u, mixed $date=null):ParticipationStreak{return DB::transaction(function()use($u,$date){$d=CarbonImmutable::parse($date??now('UTC'))->utc()->toDateString();$s=ParticipationStreak::firstOrCreate(['user_id'=>$u->id]);if($s->last_qualifying_date?->toDateString()===$d)return $s;$y=CarbonImmutable::parse($d)->subDay()->toDateString();$next=$s->last_qualifying_date?->toDateString()===$y?$s->current_streak+1:1;$s->update(['current_streak'=>$next,'longest_streak'=>max($s->longest_streak,$next),'last_qualifying_date'=>$d,'active_competitive_days'=>$s->active_competitive_days+1]);return $s->refresh();});} }
